{"query": "
-- ============================================================
-- SMOKE TEST: Verify the trigger blocks inconsistent updates
-- This should FAIL with an exception (that's the correct behavior)
-- ============================================================
DO $$
DECLARE
    v_set_num TEXT;
    v_old_parts INTEGER;
    caught BOOLEAN := false;
BEGIN
    -- Pick a set that has inventory parts
    SELECT ls.set_num, ls.num_parts
      INTO v_set_num, v_old_parts
      FROM public.lego_sets ls
      JOIN public.lego_inventories li ON li.set_num = ls.set_num
      JOIN public.lego_inventory_parts lip ON lip.inventory_id = li.id
     WHERE lip.is_spare = false
     LIMIT 1;

    BEGIN
        -- Try to set num_parts to a deliberately wrong value
        UPDATE public.lego_sets
           SET num_parts = -9999
         WHERE set_num = v_set_num;

        -- If we reach here, trigger did NOT fire — that's a failure
        RAISE EXCEPTION 'FAIL: trigger did not block the inconsistent update!';
    EXCEPTION
        WHEN OTHERS THEN
            IF SQLERRM LIKE '%Inconsistent part count%' THEN
                caught := true;
                RAISE NOTICE 'PASS: Trigger correctly blocked inconsistent update for set % (SQLERRM: %)', v_set_num, SQLERRM;
            ELSE
                RAISE EXCEPTION 'UNEXPECTED ERROR: %', SQLERRM;
            END IF;
    END;

    IF NOT caught THEN
        RAISE EXCEPTION 'FAIL: Expected trigger exception was not caught!';
    END IF;
END;
$$;
"}
